    """group=普通群或超级群；private=真人私聊。频道广播和机器人对话不收。"""
    if entity is None:
        return ''
    name = type(entity).__name__
    if name == 'User':
        if getattr(entity, 'bot', False):
            return ''
        return 'private'
    if name == 'Chat':
